using System;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Linq;using System.Windows.Forms;
namespace IDSketcher{
partial class VectorShape{
 public float CornerRadius;
 public bool CanRadius{get{return Handles.Count==0&&Points.Count>=3&&(Kind=="Polyline"||Kind=="Polygon"||Kind=="Line");}}
 struct Fillet{public PointF In,Out,Centre;public float Radius,Start,Sweep;}
 Fillet Corner(int index){var p=Points[index];var prev=Points[(index+Points.Count-1)%Points.Count];var next=Points[(index+1)%Points.Count];float a=StrokeSession.Distance(p,prev),b=StrokeSession.Distance(p,next);var result=new Fillet{In=p,Out=p};if(a<.001||b<.001)return result;float ux=(prev.X-p.X)/a,uy=(prev.Y-p.Y)/a,vx=(next.X-p.X)/b,vy=(next.Y-p.Y)/b;double angle=Math.Acos(Math.Max(-1,Math.Min(1,ux*vx+uy*vy)));if(angle<.001||angle>Math.PI-.001)return result;double tangent=Math.Tan(angle/2);float distance=(float)Math.Min(CornerRadius/tangent,Math.Min(a,b)*.5);if(distance<.001)return result;float radius=(float)(distance*tangent),bx=ux+vx,by=uy+vy,len=(float)Math.Sqrt(bx*bx+by*by),centreDistance=(float)(radius/Math.Sin(angle/2));var centre=new PointF(p.X+bx/len*centreDistance,p.Y+by/len*centreDistance);var enter=new PointF(p.X+ux*distance,p.Y+uy*distance);var exit=new PointF(p.X+vx*distance,p.Y+vy*distance);float start=(float)(Math.Atan2(enter.Y-centre.Y,enter.X-centre.X)*180/Math.PI),end=(float)(Math.Atan2(exit.Y-centre.Y,exit.X-centre.X)*180/Math.PI),sweep=end-start;while(sweep>180)sweep-=360;while(sweep< -180)sweep+=360;return new Fillet{In=enter,Out=exit,Centre=centre,Radius=radius,Start=start,Sweep=sweep};}
 GraphicsPath RoundedPath(){var path=new GraphicsPath();bool closed=Kind=="Polygon";var corners=new Fillet[Points.Count];for(int i=0;i<Points.Count;i++)corners[i]=!closed&&(i==0||i==Points.Count-1)?new Fillet{In=Points[i],Out=Points[i]}:Corner(i);PointF current=closed?corners[0].Out:Points[0];int stop=closed?Points.Count:Points.Count-1;for(int n=1;n<=stop;n++){int i=n%Points.Count;var corner=corners[i];path.AddLine(current,corner.In);if(corner.Radius>.001f)path.AddArc(corner.Centre.X-corner.Radius,corner.Centre.Y-corner.Radius,2*corner.Radius,2*corner.Radius,corner.Start,corner.Sweep);current=corner.Out;}if(closed)path.CloseFigure();return path;}
}
partial class Canvas{
 public float VectorRadius;
 public void ChangeVectorRadius(float value){if(Doc==null||!Doc.Selected.IsVector||Doc.Selected.IsLocked)return;value=Math.Max(0,Math.Min(500,value));VectorRadius=value;var targets=selectedPaths.Where(s=>s.CanRadius&&s.CornerRadius!=value&&Doc.Selected.Vectors.Contains(s)).ToArray();if(targets.Length==0)return;if(BeforeStroke!=null)BeforeStroke();foreach(var shape in targets)shape.CornerRadius=value;Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();Invalidate();}
 public bool CanSetRadius{get{return Doc!=null&&Doc.Selected.IsVector&&!Doc.Selected.IsLocked&&(selectedPaths.Any(s=>s.CanRadius)||VectorMode=="Polyline"||VectorMode=="Polygon"||VectorMode=="Rectangle");}}
}
partial class Studio{
 public void TestRadiusAndNavigation(){
  previewing=true;Show();SetDocument(new Document("A4",100),null);AddTypedLayer(true);canvas.Zoom=1;canvas.Offset=PointF.Empty;vectorMode.SelectedItem="Polyline";foreach(var p in new[]{new Point(50,50),new Point(150,50),new Point(150,150)})canvas.TestDrag(p,p);canvas.FinishVector();vectorPicker.PerformClick();var points=canvas.Doc.Selected.Vectors[0].Points.ToArray();canvas.TestStylePick(new PointF(80,50),false);int history=undo.Count;radiusSlider.Value=20;var shape=canvas.Doc.Selected.Vectors[0];if(shape.CornerRadius!=20||undo.Count!=history+1||!shape.Points.SequenceEqual(points))throw new Exception("Radius must preserve editable points and record undo");using(var path=shape.Path()){if(path.PointCount<=3||path.IsOutlineVisible(new PointF(150,50),new Pen(Color.Black,3))||!path.IsOutlineVisible(new PointF(130,50),new Pen(Color.Black,3)))throw new Exception("Tangent corner rounding");}
  Travel(undo,redo);if(canvas.Doc.Selected.Vectors[0].CornerRadius!=0)throw new Exception("Radius undo");Travel(redo,undo);if(canvas.Doc.Selected.Vectors[0].CornerRadius!=20)throw new Exception("Radius redo");string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(file);using(var loaded=Document.Load(file))if(loaded.Selected.Vectors[0].CornerRadius!=20||!loaded.Selected.Vectors[0].Points.SequenceEqual(points))throw new Exception("Radius persistence");}finally{File.Delete(file);}
  var polygon=new VectorShape{Kind="Polygon",CornerRadius=500,Points=new System.Collections.Generic.List<PointF>{new PointF(20,20),new PointF(80,20),new PointF(80,80),new PointF(20,80)}};using(var path=polygon.Path())if(!path.IsVisible(new PointF(50,50))||path.IsVisible(new PointF(20,20)))throw new Exception("Clamped polygon radius");var copy=polygon.Copy();if(copy.CornerRadius!=500||!copy.Points.SequenceEqual(polygon.Points))throw new Exception("Radius copy");
  var target=new VectorShape{Kind="Polyline",Colour=Color.Blue,Points=new System.Collections.Generic.List<PointF>{new PointF(50,250),new PointF(150,250),new PointF(150,350)}};canvas.Doc.Selected.Vectors.Add(target);canvas.Doc.Selected.InvalidateVectors();canvas.TestStylePick(new PointF(80,50),false);canvas.TestStylePick(new PointF(80,250),true);canvas.CopySelectedStyle();if(target.CornerRadius!=20)throw new Exception("Copy style includes corner radius");canvas.TestStylePick(new PointF(80,50),false);SyncRadiusControls();if(radiusSlider.Top<=strokeValueBox.Bottom||radiusLabel.Top<=strokeValueBox.Bottom||!radiusSlider.Enabled)throw new Exception("Radius control below stroke row");paletteTabs.SelectedTab=colourPage;canvas.Fit();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"radius-controls-preview.png"));}
  using(var view=new Canvas())view.TestFastNavigation();dirty=false;
 }
 TrackBar radiusSlider;Label radiusLabel;bool syncingRadius;
 void AddRadiusControls(Panel panel){radiusLabel=new Label{Text="RADIUS - 0 PX",TextAlign=ContentAlignment.MiddleCenter,Parent=panel};radiusSlider=new TrackBar{Minimum=0,Maximum=500,TickStyle=TickStyle.None,AutoSize=false,Parent=panel};radiusSlider.ValueChanged+=delegate{radiusLabel.Text="RADIUS - "+radiusSlider.Value+" PX";if(!syncingRadius)canvas.ChangeVectorRadius(radiusSlider.Value);};SyncRadiusControls();}
 void SyncRadiusControls(){if(radiusSlider==null)return;bool vector=canvas.Doc!=null&&canvas.Doc.Selected.IsVector;radiusSlider.Visible=radiusLabel.Visible=vector;radiusSlider.Enabled=radiusLabel.Enabled=canvas.CanSetRadius;syncingRadius=true;try{radiusSlider.Value=(int)Math.Round(canvas.SelectedVector!=null&&canvas.SelectedVector.CanRadius?canvas.SelectedVector.CornerRadius:canvas.VectorRadius);radiusLabel.Text="RADIUS - "+radiusSlider.Value+" PX";}finally{syncingRadius=false;}}
}
